void Draw();
void AddSprite(class SpriteComponent* sprite);
void RemoveSprite(class SpriteComponent* sprite);
class Texture* GetTexture(const std::string& fileName);
class Mesh* GetMesh(const std::string& fileName);
private:
bool LoadShaders();
