Note that PlayEvent no longer calls release on the event instance. Instead,
AudioSystem::Update now handles cleaning up event instances that are no longer needed.
Every frame, Update checks the playback state of each event instance in the map by using
getPlayBackState. It releases any event instances in the stopped state and then removes
them from the map. This assumes that stopping an event means freeing it is okay. A caller
who wants to keep an event around can pause it instead of stopping it. Listing 7.4 shows the
implementation of Update.
Listing 7.4 AudioSystem::Update Implementation with Event IDs
void AudioSystem::Update(float deltaTime)
{
// Find any stopped event instances
std::vector<unsigned int> done;
for (auto& iter : mEventInstances)
{
FMOD::Studio::EventInstance* e = iter.second;
// Get the state of this event
FMOD_STUDIO_PLAYBACK_STATE state;
e->getPlaybackState(&state);
if (state == FMOD_STUDIO_PLAYBACK_STOPPED)
{
// Release the event and add id to done
e->release();
done.emplace_back(iter.first);
}
}
// Remove done event instances from map
for (auto id : done)
{
mEventInstances.erase(id);
}
// Update FMOD
mSystem->update();
}
